A={(0,0),(0,2),(1,1),(2,1)}
B={(0,0),(1,1),(1,2),(2,0)}
def transforms(S):
 out=[]
 for k in range(4):
  pts=S.copy()
  # apply rot k cw on 3x3
  for _ in range(k): pts={(c,2-r) for r,c in pts}
  out.append(('rot'+str(k),pts))
  out.append(('refrot'+str(k),{(r,2-c) for r,c in pts}))
 return out
[(n,s) for n,s in transforms(A) if s==B]

