# candidate shapes any 4-point subsets that are congruent to source candidate under a dihedral transform, allowing translate
cand={(0,0),(0,2),(1,1),(2,1)}
# generate normalized transformed shapes
shapes=set()
for n,s in transforms(cand):
 mins=(min(r for r,c in s), min(c for r,c in s)); norm=frozenset((r-mins[0],c-mins[1]) for r,c in s)
 shapes.add(norm)
for name,S in [('top',top),('bot',bot)]:
 found=[]
 for sub in __import__('itertools').combinations(S,4):
  rs=[r for r,c in sub]; cs=[c for r,c in sub]; norm=frozenset((r-min(rs),c-min(cs)) for r,c in sub)
  if norm in shapes: found.append((sub,norm))
 print(name,found)

